nb_drones: 12

# START / END
start_hub: start 0 0 [max_drones=20]
end_hub: goal 14 0 [max_drones=20]

# WAITING AREAS
hub: waiting_area1 2 2 [zone=priority max_drones=3 color=blue]
hub: waiting_area2 4 2 [zone=priority max_drones=3 color=blue]
hub: waiting_area3 6 2 [zone=priority max_drones=3 color=blue]

# GATES
hub: gate1 2 0 [max_drones=2 color=orange]
hub: gate2 4 0 [max_drones=2 color=orange]
hub: gate3 6 0 [max_drones=2 color=orange]

# PRIORITY BYPASS
hub: priority_bypass1 5 4 [zone=priority max_drones=2 color=cyan]
hub: priority_bypass2 7 4 [zone=priority max_drones=2 color=cyan]

# RESTRICTED TUNNELS
hub: restricted_tunnel1 8 0 [zone=restricted max_drones=1 color=red]
hub: restricted_tunnel2 10 0 [zone=restricted max_drones=1 color=red]
hub: restricted_tunnel3 12 0 [zone=restricted max_drones=1 color=red]

# CONVERGENCE + FINAL BOTTLENECK
hub: convergence 11 2 [zone=priority max_drones=4 color=yellow]
hub: final_bottleneck 13 0 [max_drones=1 color=orange]

# CONNECTIONS FROM START
connection: start-gate1
connection: start-gate2
connection: start-gate3

# VERTICAL ACCESS TO WAITING AREAS
connection: gate1-waiting_area1
connection: gate2-waiting_area2
connection: gate3-waiting_area3

# WAITING AREA CHAIN
connection: waiting_area1-waiting_area2
connection: waiting_area2-waiting_area3

# PRIORITY BYPASS ROUTE
connection: waiting_area1-priority_bypass1
connection: waiting_area2-priority_bypass2
connection: priority_bypass1-priority_bypass2
connection: priority_bypass2-convergence [max_link_capacity=2]

# RESTRICTED MAIN ROUTE
connection: gate3-restricted_tunnel1
connection: restricted_tunnel1-restricted_tunnel2
connection: restricted_tunnel2-restricted_tunnel3
connection: restricted_tunnel3-convergence

# DIRECT WAITING AREA MERGE
connection: waiting_area3-convergence

# FINAL EXIT
connection: convergence-final_bottleneck
connection: final_bottleneck-goal
